237	    /**
238	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
239	     * already reached this many owners is rejected as a conflict.
240	     */
241	    static final int MAX_OWNERS_PER_CITY = 50;
242	
243	    /**
244	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
245	     * already reached this many registrations is rejected as a rate-limit violation.
246	     */
247	    static final int MAX_OWNERS_PER_DAY = 100;
248	
249	    @Override
250	    @Transactional
251	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
252	        if (ownerRepository.existsByTelephone(owner.getTelephone())) {
253	            throw new DuplicateTelephoneException(owner.getTelephone());
254	        }
255	        List<Owner> householdMembers = findHouseholdMembers(owner);
256	        if (!householdMembers.isEmpty() && !sharesHousehold) {
257	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
258	        }
259	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
260	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
261	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
262	        }
263	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
264	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
265	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
266	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
267	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
268	        }
269	        owner.setNamesakeCount(countNamesakes(owner));
270	        owner.setCustomerCode(CustomerCodeGenerator.format(
271	            owner.getCity(), owner.getLastName(), ownersInCity + 1));
272	        if (!householdMembers.isEmpty()) {
273	            owner.setHouseholdId(joinHousehold(owner, householdMembers));
274	        }
275	        ownerRepository.save(owner);
276	        return owner.getHouseholdId();
277	    }
