279	    /**
280	     * Assign the stable household identifier to the new owner and to every existing member of the
281	     * household, persisting the members whose identifier changes, and return the shared identifier.
282	     */
283	    private String joinHousehold(Owner owner, List<Owner> householdMembers) {
284	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
285	        for (Owner member : householdMembers) {
286	            if (!householdId.equals(member.getHouseholdId())) {
287	                member.setHouseholdId(householdId);
288	                ownerRepository.save(member);
289	            }
290	        }
291	        return householdId;
292	    }
