302	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
303	     */
304	    private int countNamesakes(Owner owner) {
305	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
306	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
307	            .count();
308	    }
309	
310	    /**
311	     * Find the existing owners that already share this owner's household, i.e. that have the same last name and
312	     * address compared case-insensitively and with runs of whitespace collapsed.
313	     */
314	    private List<Owner> findHouseholdMembers(Owner owner) {
315	        String address = TextNormalizer.normalize(owner.getAddress());
316	        if (address == null) {
317	            return List.of();
318	        }
319	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
320	            .filter(existing -> address.equals(TextNormalizer.normalize(existing.getAddress())))
321	            .toList();
322	    }
